const body = $json.body || {};
const headers = $json.headers || {};
const expectedSecret = 'O2LwUFK2HvTDhG53';
const receivedSecret = headers['x-lms-whatsapp-secret'] || headers['X-Lms-Whatsapp-Secret'] || '';
if (expectedSecret && receivedSecret !== expectedSecret) throw new Error('Invalid LMS WhatsApp forwarding secret');

const rawRecipients = Array.isArray(body.recipients) && body.recipients.length
  ? body.recipients
  : body.to
    ? [body.to]
    : ['8017996184', '6290349998'];

const normalizeIndianWhatsAppNumber = (value) => {
  const digits = String(value || '').replace(/\D/g, '');
  if (!digits) return '';
  if (digits.length === 10 && /^[6-9]/.test(digits)) return `91${digits}`;
  if (digits.length === 12 && digits.startsWith('91')) return digits;
  return digits;
};

const bodyComponent = Array.isArray(body.components)
  ? body.components.find((component) => String(component?.type || '').toLowerCase() === 'body')
  : null;

const componentParameters = Array.isArray(bodyComponent?.parameters)
  ? bodyComponent.parameters
      .map((parameter) => String(parameter?.text ?? parameter?.value ?? '').slice(0, 1024))
      .filter(Boolean)
  : [];

const rawBodyParameters = Array.isArray(body.bodyParameters)
  ? body.bodyParameters
  : Array.isArray(body.templateVariables)
    ? body.templateVariables
    : componentParameters;

const bodyParameters = rawBodyParameters
  .map((value) => String(value || '').slice(0, 1024))
  .filter(Boolean);

const language = String(body.language || body.language_code || 'en').trim();
const templateName = String(body.templateName || body.template_name || 'hello_world_2').trim();
const recipients = [...new Set(rawRecipients.map(normalizeIndianWhatsAppNumber).filter(Boolean))];

return recipients.map((to) => ({
  json: {
    to,
    templateName,
    language,
    bodyParameters,
    metadata: body.metadata || {},
  },
}));

const bodyParameters = Array.isArray($json.bodyParameters) ? $json.bodyParameters : [];
const components = bodyParameters.length
  ? {
      component: [
        {
          type: 'body',
          bodyParameters: {
            parameter: bodyParameters.map((text) => ({
              type: 'text',
              text: String(text),
            })),
          },
        },
      ],
    }
  : {};

const digits = String($json.to || '').replace(/\D/g, '');
const recipientPhoneNumber = digits.length === 10 && /^[6-9]/.test(digits) ? `91${digits}` : digits;

return [
  {
    json: {
      ...$json,
      phoneNumberId: '1203164092890708',
      recipientPhoneNumber,
      template: `${$json.templateName}|${$json.language || 'en'}`,
      components,
    },
  },
];

const items = $input.all();
const results = items.map((item) => {
  const json = item.json || {};
  const message = Array.isArray(json.messages) ? json.messages[0] : null;
  const contact = Array.isArray(json.contacts) ? json.contacts[0] : null;
  return {
    phoneNumber: contact?.wa_id || json.recipientPhoneNumber || json.to || '',
    to: contact?.wa_id || json.recipientPhoneNumber || json.to || '',
    ok: Boolean(message?.id || json.messaging_product),
    status: message?.message_status || 'accepted',
    metaMessageId: message?.id || '',
    templateName: json.templateName || '',
    debug: {
      sender: 'n8n_native_whatsapp_node',
      templateName: json.templateName || '',
      templateLanguage: json.language || '',
      recipient: contact?.wa_id || json.recipientPhoneNumber || json.to || '',
      metaMessageId: message?.id || '',
      raw: json,
    },
  };
});
return [{ json: { ok: results.every((result) => result.ok), results } }];
